package net.civeira.phylax.features.notification.message.infrastructure.repository;

import java.util.Iterator;
import java.util.List;
import java.util.function.BiFunction;

import net.civeira.phylax.common.algorithms.Slider;
import net.civeira.phylax.features.notification.message.domain.Message;
import net.civeira.phylax.features.notification.message.domain.gateway.MessageCursor;
import net.civeira.phylax.features.notification.message.domain.gateway.MessageFilter;

class MessageSlider extends Slider<Message> {

  /**
   * @autogenerated SlideGenerator
   */
  private final MessageCursor cursor;

  /**
   * @autogenerated SlideGenerator
   */
  private final MessageFilter filter;

  /**
   * @autogenerated SlideGenerator
   */
  private final BiFunction<MessageFilter, MessageCursor, Iterator<Message>> gateway;

  /**
   * @autogenerated SlideGenerator
   * @param multi
   * @param limit
   * @param gateway
   * @param filter
   * @param cursor
   */
  MessageSlider(final Iterator<Message> multi, final int limit,
      final BiFunction<MessageFilter, MessageCursor, Iterator<Message>> gateway,
      final MessageFilter filter, final MessageCursor cursor) {
    super(multi, limit);
    this.gateway = gateway;
    this.filter = filter;
    this.cursor = cursor;
  }

  /**
   * @autogenerated SlideGenerator
   * @param messages
   * @param limit
   * @return
   */
  @Override
  public Iterator<Message> next(List<Message> messages, int limit) {
    Message last = messages.get(messages.size() - 1);
    MessageCursor cr = this.cursor.withSinceUid(last.getUid()).withLimit(limit);
    return gateway.apply(this.filter, cr);
  }
}
